CREATE POLICY payment_proofs_staff_read ON storage.objects FOR SELECT TO authenticated USING (bucket_id='payment-proofs' AND private.foundation_staff(((storage.foldername(name))[1])::uuid));
CREATE POLICY payment_proofs_staff_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id='payment-proofs' AND private.foundation_staff(((storage.foldername(name))[1])::uuid));
CREATE POLICY payment_proofs_staff_delete ON storage.objects FOR DELETE TO authenticated USING (bucket_id='payment-proofs' AND private.foundation_staff(((storage.foldername(name))[1])::uuid));